48	    private static final class SearchInput {
49	        private final int[] sortedNumbers;
50	        private final int target;
51	
52	        private SearchInput(int[] sortedNumbers, int target) {
53	            this.sortedNumbers = sortedNumbers;
54	            this.target = target;
55	        }
56	
57	        private boolean matches(int index) {
58	            return sortedNumbers[index] == target;
59	        }
60	
61	        private boolean targetIsAfter(int index) {
62	            return sortedNumbers[index] < target;
63	        }
64	    }
65	
66	    private static final class SearchBounds {
67	        private final int left;
68	        private final int right;
69	
70	        private SearchBounds(int left, int right) {
71	            this.left = left;
72	            this.right = right;
73	        }
74	
75	        private static SearchBounds forArray(int[] sortedNumbers) {
76	            return new SearchBounds(0, sortedNumbers.length - 1);
77	        }
78	
79	        private boolean hasRemainingValues() {
80	            return left <= right;
81	        }
82	
83	        private int midpoint() {
84	            return left + (right - left) / 2;
85	        }
86	
87	        private SearchBounds after(int middle) {
88	            return new SearchBounds(middle + 1, right);
89	        }
90	
91	        private SearchBounds before(int middle) {
92	            return new SearchBounds(left, middle - 1);
93	        }
94	    }
